function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof PALA_INFO&&(e.innerHTML=PALA_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderEcology(){if("undefined"==typeof ECOLOGY_HYDROLOGY)return;const e=document.getElementById("eco-overview"),n=document.getElementById("eco-hydrology"),t=document.getElementById("eco-legend"),s=document.getElementById("eco-status");e&&(e.innerHTML=`<strong>Overview:</strong> ${ECOLOGY_HYDROLOGY.overview}`),n&&(n.innerHTML=`<strong>Freshwater Ecology:</strong> ${ECOLOGY_HYDROLOGY.freshwaterEcology}`),t&&(t.innerHTML=`<strong>Mara Folk Legend:</strong> ${ECOLOGY_HYDROLOGY.legend}`),s&&(s.innerHTML=`<strong>Conservation Status:</strong> ${ECOLOGY_HYDROLOGY.conservationStatus}`)}function renderSpecies(){const e=document.getElementById("species-grid");e&&"undefined"!=typeof BIRD_FISH_SPECIES&&(e.innerHTML=BIRD_FISH_SPECIES.map(e=>`\n        <div class="species-card">\n            <img src="${e.image}" alt="${e.name}" loading="lazy" />\n            <div class="species-card-body">\n                <div class="species-header">\n                    <h3>${e.name} ${e.icon}</h3>\n                    <span class="status-badge">${e.status}</span>\n                </div>\n                <p class="scientific-name"><em>${e.scientificName}</em></p>\n                <p>${e.description}</p>\n                <div class="bird-meta">\n                    <span>🗓️ ${e.season}</span> | \n                    <span>📏 ${e.wingspan||e.size}</span>\n                </div>\n            </div>\n        </div>\n    `).join(""))}function renderHotspots(){const e=document.getElementById("hotspots-grid");e&&"undefined"!=typeof MAP_HOTSPOTS&&(e.innerHTML=MAP_HOTSPOTS.map(e=>`\n        <div class="hotspot-card">\n            <h3>📍 ${e.title}</h3>\n            <span class="spot-type">${e.type}</span>\n            <p>${e.description}</p>\n            <small>Coordinates: ${e.lat}° N, ${e.lng}° E</small>\n        </div>\n    `).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" />\n            <p>${e.caption}</p>\n        </div>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderEcology(),renderSpecies(),renderHotspots(),renderGallery(),initThemeToggle()});